1: import { useCallback, useEffect, useRef } from 'react'
2: import { pickRandomAccount, resolveJudgeKey, type JudgeAction } from '../../lib/judgeMode'
3: import { SHOCK_PRESETS } from '../../lib/shockPresets'
4: import { IDLE_TWIST, sameTwist } from '../../lib/shocks'
5: import { useConsole } from '../../state/consoleStore'
6: 
7: /**
8:  * The E6 wiring layer: one dispatcher that maps a JudgeAction onto the
9:  * existing console store actions (plus the lookup focus), and one
10:  * window keydown listener that resolves a key press through
11:  * resolveJudgeKey before it ever reaches the dispatcher. Both live
12:  * outside React state: the store is the state, the listener is a
13:  * subscription, and neither re-renders the page on a key press.
14:  *
15:  * The layered dismiss is decided here because it needs the live store:
16:  * an open typed shock gate cancels first, then a non empty lookup
17:  * query clears, then a selection or a live twist resets everything, and
18:  * with nothing on screen the key does nothing at all.
19:  */
20: 
21: /** Options the dispatcher takes; the rng pins the N draw in tests. */
22: export interface JudgeDispatcherOptions {
23:   /** Injectable random source for the random account draw. */
24:   rng?: () => number
25: }
26: 
27: /** One judge action applied to the live console store. */
28: export type JudgeDispatcher = (action: JudgeAction) => void
29: 
30: /** True while the typed shock gate reads or waits to confirm. */
31: export function isTypedGateOpen(status: string): boolean {
32:   return status === 'reading' || status === 'pending'
33: }
34: 
35: /** True when the key landed in an input, textarea, select, or editable. */
36: export function isTextEntryTarget(target: EventTarget | null): boolean {
37:   if (target === null || typeof (target as Partial<Element>).tagName !== 'string') {
38:     return false
39:   }
40:   const element = target as HTMLElement
41:   const tag = element.tagName
42:   if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') {
43:     return true
44:   }
45:   return element.isContentEditable === true
46: }
47: 
48: /** The layered Esc rule, decided against the live store. */
49: function runDismiss(): void {
50:   const state = useConsole.getState()
51:   if (isTypedGateOpen(state.typedStatus)) {
52:     state.cancelTypedShock()
53:     return
54:   }
55:   if (state.query.length > 0) {
56:     state.setQuery('')
57:     return
58:   }
59:   if (state.selectedId !== null || !sameTwist(state.twist, IDLE_TWIST)) {
60:     state.resetAll()
61:     return
62:   }
63:   // Nothing on screen: Esc is a no op.
64: }
65: 
66: /**
67:  * Build the dispatcher: a stable function that reads the store on
68:  * demand, so the bar buttons and the key listener share one mapping.
69:  * Guards inform, they never gate: the random draw and the preset keys
70:  * only ever hand the store ids and presets it already accepts.
71:  */
72: export function useJudgeDispatcher(options: JudgeDispatcherOptions = {}): JudgeDispatcher {
73:   const rngRef = useRef<(() => number) | undefined>(options.rng)
74:   rngRef.current = options.rng
75: 
76:   return useCallback((action: JudgeAction) => {
77:     const store = useConsole.getState()
78:     switch (action.kind) {
79:       case 'twist': {
80:         const preset = SHOCK_PRESETS[action.preset - 1]
81:         if (preset) {
82:           store.applyPreset(preset.id)
83:         }
84:         return
85:       }
86:       case 'reset_twist':
87:         store.resetTwist()
88:         return
89:       case 'reset_all':
90:         store.resetAll()
91:         return
92:       case 'focus_lookup': {
93:         const input = document.getElementById('account-lookup')
94:         if (input instanceof HTMLElement) {
95:           input.focus()
96:         }
97:         return
98:       }
99:       case 'dismiss':
100:         runDismiss()
101:         return
102:       case 'random_account': {
103:         const id = pickRandomAccount(store.bundle, {
104:           excludeId: store.selectedId,
105:           rng: rngRef.current,
106:         })
107:         if (id !== null) {
108:           store.selectAccount(id)
109:         }
110:         return
111:       }
112:     }
113:   }, [])
114: }
115: 
116: /**
117:  * Subscribe the window keydown listener: bubble phase, straight to
118:  * resolveJudgeKey with the live context, isComposing and repeat
119:  * ignored before anything else, and preventDefault only for the lookup
120:  * focus so a slash in the lookup still types a slash.
121:  */
122: export function useJudgeShortcuts(dispatch?: JudgeDispatcher): void {
123:   const ownDispatcher = useJudgeDispatcher()
124:   const dispatchAction = dispatch ?? ownDispatcher
125: 
126:   useEffect(() => {
127:     const onKeyDown = (event: KeyboardEvent): void => {
128:       if (event.isComposing || event.repeat) {
129:         return
130:       }
131:       const state = useConsole.getState()
132:       const action = resolveJudgeKey(
133:         event,
134:         {
135:           // A real key press targets the focused element, so either
136:           // reading says the same thing: the key landed in a text entry.
137:           inTextEntry:
138:             isTextEntryTarget(event.target) || isTextEntryTarget(document.activeElement),
139:           typedGateOpen: isTypedGateOpen(state.typedStatus),
140:         },
141:       )
142:       if (!action) {
143:         return
144:       }
145:       if (action.kind === 'focus_lookup') {
146:         event.preventDefault()
147:       }
148:       dispatchAction(action)
149:     }
150:     window.addEventListener('keydown', onKeyDown)
151:     return () => window.removeEventListener('keydown', onKeyDown)
152:   }, [dispatchAction])
153: }

